// Placement / app page: POST AUTH_ID, member_id, PLACEMENT, PLACEMENT_OPTIONS (JSON string); DOMAIN in the query.
const b = $json.body ?? {}, q = $json.query ?? {};
let opts = {};
try { opts = typeof b.PLACEMENT_OPTIONS === 'string' ? JSON.parse(b.PLACEMENT_OPTIONS) : (b.PLACEMENT_OPTIONS ?? {}); } catch { opts = {}; }
return [{ json: { auth_id: b.AUTH_ID ?? null, member_id: b.member_id ?? null, domain: String(q.DOMAIN ?? b.DOMAIN ?? '').toLowerCase(),
                  placement: b.PLACEMENT ?? null, deal_id: Number(opts.ID) || null } }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

function describe(e) {
  const d = e.detail ?? {};
  switch (e.step) {
    case 'normalize': return ['Нормализация', `телефон ${d.phone ?? '—'}, e-mail ${d.email ?? '—'}, ИНН ${d.inn_valid ? 'корректный' : 'нет/неверный'}${(d.warnings ?? []).length ? '. ' + d.warnings.join('; ') : ''}`];
    case 'score': return ['Оценка', `${d.method === 'rules' ? 'по правилам' : d.method}: тема ${d.topic}, срочность ${d.urgency}${d.budget ? `, бюджет ${d.budget} ₽` : ''}`];
    case 'dedup': return ['Дедупликация', d.contact_id ? `контакт #${d.contact_id} найден по ${d.matched_by === 'phone' ? 'телефону' : 'e-mail'}${d.owner_id ? `, его менеджер #${d.owner_id}` : ''}` : 'контакт не найден, создан новый' + (d.existing_deal_id ? `; сделка #${d.existing_deal_id} уже была (повторная попытка)` : '')];
    case 'enrich': return ['Обогащение', d.source === 'cache' ? `DaData (кэш): ${d.name ?? '—'}` : d.error ? `DaData недоступна: ${d.error}` : d.found === false ? 'DaData: организация не найдена' : `DaData: ${d.name ?? '—'}, ${d.status ?? ''}, ${d.region ?? ''}`];
    case 'route': return ['Назначение', `менеджер #${d.manager_id}: ${d.reason}`];
    case 'crm': return ['CRM', `${d.repaired ? 'дозаведено после сбоя: ' : 'создано: '}${(d.created ?? []).join(', ')}`];
    case 'deferred': return ['Отложено', d.reason];
    case 'failed': return ['Ошибка', `попытка ${d.attempt}: ${d.error}`];
    case 'rejected': return ['Отклонено', d.reason];
    case 'sla_escalated': return ['Эскалация SLA', `уведомлены менеджер #${d.manager_id} и РОП`];
    case 'sla_closed': return ['SLA закрыт', `${d.status === 'met' ? 'ответ в срок' : 'SLA нарушен'}${d.response_min !== undefined ? `, ответ через ${d.response_min} мин` : ''} (${d.by})`];
    case 'robot_inn_check': return ['Робот: проверка ИНН', `${d.inn}: ${d.check_result}${d.company_name ? ` — ${d.company_name}` : ''}`];
    default: return [e.step, JSON.stringify(d)];
  }
}

const j = $json.j, a = j.a;
const fmt = (t) => t ? new Date(t).toLocaleString('ru-RU', { timeZone: 'Europe/Moscow', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' }) : '—';
let body;
if (!a) {
  body = `<h1>Интеграция</h1><p class="muted">Сделка #${esc(j.deal_id)} создана не через b24-lead-hub — журнала нет.</p>`;
} else {
  const badge = a.sla_status === 'met' ? '<span class="b ok">ответ в срок</span>' : a.sla_status === 'breached' ? '<span class="b bad">SLA нарушен</span>' : '<span class="b wait">ожидает ответа</span>';
  const rows = j.events.map((e) => { const [t, d] = describe(e); return `<tr><td class="muted">${esc(fmt(e.at))}</td><td><b>${esc(t)}</b></td><td>${esc(d)}</td><td class="muted"><code>${esc(e.execution_id ?? '')}</code></td></tr>`; }).join('');
  body = `<h1>Что интеграция сделала и почему</h1>
<p class="muted">Заявка из «${esc(a.source)}» ${esc(fmt(a.received_at))} · ключ <code>${esc(a.idempotency_key)}</code> · попыток обработки: ${esc(a.attempt_count)}</p>
<div><span class="kpi">Менеджер<b>#${esc(a.manager_id)}</b></span><span class="kpi">SLA до<b>${esc(fmt(a.sla_due))}</b></span><span class="kpi">Статус<b>${badge}</b></span></div>
<p>${esc(a.reason)}</p>
<h2>Журнал</h2><table><tr><th>Время (МСК)</th><th>Шаг</th><th>Что и почему</th><th>Execution</th></tr>${rows}</table>`;
}
return [{ json: { html: `<!doctype html><html><head><meta charset="utf-8"><title>Интеграция</title><style>body{font:14px/1.45 -apple-system,Segoe UI,Roboto,sans-serif;color:#1f2933;margin:16px;background:#fff}h1{font-size:18px;margin:0 0 4px}h2{font-size:15px;margin:20px 0 8px}.muted{color:#6b7785}table{border-collapse:collapse;width:100%}td,th{border-bottom:1px solid #e6e9ee;padding:6px 8px;text-align:left;vertical-align:top}th{font-weight:600;color:#52606d;font-size:12px;text-transform:uppercase;letter-spacing:.03em}.b{display:inline-block;padding:2px 8px;border-radius:10px;font-size:12px;font-weight:600}.ok{background:#e3f6ea;color:#16794c}.bad{background:#fde8e8;color:#b42318}.wait{background:#fff4e0;color:#a15c00}.kpi{display:inline-block;margin:0 24px 8px 0}.kpi b{display:block;font-size:22px}code{font-size:12px}</style></head><body>${body}</body></html>` } }];
